SELECT id, tenant_id, operation_type, target_application_id, requested_by_user_id, requested_by_email, status,
       approver_user_id, approver_email, decision_reason, before_snapshot, after_snapshot, created_at,
       decided_at, executed_at
FROM approval_requests
WHERE tenant_id = #{tenantId}
  AND id = #{requestId}
